using VitalTrek.API.IncidentResponse.Domain.Model.ValueObjects;

namespace VitalTrek.API.IncidentResponse.Domain.Model.Commands;

/// <summary>
///     Command to record an evacuation step captured by the assigned field guide, possibly offline.
/// </summary>
/// <param name="AgencyId">The agency of the authenticated field guide.</param>
/// <param name="IncidentId">The incident identifier.</param>
/// <param name="ClientActionId">The stable identity generated by the client when the step was captured.</param>
/// <param name="Description">The description of the evacuation step.</param>
/// <param name="Location">The optional location reference.</param>
/// <param name="Status">The state of the step when it was captured.</param>
/// <param name="RecordedAt">The original capture moment.</param>
public record RecordEvacuationActionCommand(int AgencyId, int IncidentId, Guid ClientActionId, string Description,
    string? Location, EvacuationActionStatus Status, DateTimeOffset RecordedAt);
